// Parse arXiv XML response
const xml2js = require('xml2js');
const parser = new xml2js.Parser();

const items = [];
const sourceId = $node['Fetch Active Sources'].json.id;
const categorySlug = $node['Fetch Active Sources'].json.category_slug;

try {
  const result = await parser.parseStringPromise($input.item.json.body);
  const entries = result.feed.entry || [];

  for (const entry of entries) {
    const published = new Date(entry.published[0]);
    const updated = new Date(entry.updated[0]);
    const daysOld = (Date.now() - published.getTime()) / (1000 * 60 * 60 * 24);

    // Extract arXiv ID
    const arxivId = entry.id[0].split('/abs/')[1];

    // Extract categories
    const categories = entry.category ? entry.category.map(c => c.$.term) : [];
    const primaryCategory = entry['arxiv:primary_category'] ? 
      entry['arxiv:primary_category'][0].$.term : categories[0];

    // Extract authors
    const authors = entry.author ? 
      entry.author.map(a => a.name[0]).join(', ') : 'Unknown';

    // Get abstract
    const abstract = entry.summary[0].replace(/\n/g, ' ').trim();
    const abstractWords = abstract.split(/\s+/).length;

    // Calculate quality score
    let qualityScore = 0.7; // Base score for research papers

    // Bonus for good abstract length (150-500 words)
    if (abstractWords >= 150 && abstractWords <= 500) {
      qualityScore += 0.1;
    }

    // Bonus for recent publication
    if (daysOld < 7) {
      qualityScore += 0.1;
    } else if (daysOld < 30) {
      qualityScore += 0.05;
    }

    // Bonus for cross-disciplinary (multiple categories)
    if (categories.length > 1) {
      qualityScore += 0.05;
    }

    // Bonus for complete metadata
    if (entry.doi && entry['arxiv:comment']) {
      qualityScore += 0.05;
    }

    // Auto-tagging based on categories and title
    const tags = [];
    const title = entry.title[0].toLowerCase();

    // Category-based tags
    if (primaryCategory.startsWith('cs.')) tags.push('computer-science');
    if (primaryCategory.startsWith('physics.')) tags.push('physics');
    if (primaryCategory.startsWith('math.')) tags.push('mathematics');
    if (primaryCategory.includes('AI') || primaryCategory.includes('ML')) tags.push('artificial-intelligence');

    // Content-based tags
    if (title.includes('survey') || title.includes('review')) tags.push('survey');
    if (title.includes('deep learning') || title.includes('neural')) tags.push('deep-learning');
    if (title.includes('quantum')) tags.push('quantum');
    if (title.includes('climate') || title.includes('environment')) tags.push('climate');

    // Difficulty detection
    if (title.includes('introduction') || title.includes('tutorial')) {
      tags.push('beginner-friendly');
    } else if (title.includes('advanced') || title.includes('novel')) {
      tags.push('advanced');
    } else {
      tags.push('intermediate');
    }

    items.push({
      sourceId,
      externalId: arxivId,
      contentType: 'paper',
      source: 'arxiv',
      categorySlug,
      title: entry.title[0].replace(/\n/g, ' ').trim(),
      description: abstract.substring(0, 1000), // Limit to 1000 chars
      url: entry.id[0],
      pdfUrl: entry.link.find(l => l.$.type === 'application/pdf')?.$.href || null,
      author: authors.substring(0, 255), // Database limit
      publishedAt: published.toISOString(),
      updatedAt: updated.toISOString(),
      wordCount: abstractWords,
      language: 'en',
      metadata: {
        arxivId,
        primaryCategory,
        allCategories: categories,
        doi: entry.doi ? entry.doi[0] : null,
        comment: entry['arxiv:comment'] ? entry['arxiv:comment'][0] : null,
        journalRef: entry['arxiv:journal_ref'] ? entry['arxiv:journal_ref'][0] : null
      },
      qualityScore: Math.min(qualityScore, 1.0),
      popularityScore: 0, // arXiv doesn't provide view counts
      tags
    });
  }
} catch (error) {
  console.error('Error parsing arXiv XML:', error.message);
  throw new Error(`Failed to parse arXiv response: ${error.message}`);
}

return items.map(item => ({ json: item }));

// Parse PubMed JSON response and fetch details
const items = [];
const sourceId = $node['Fetch Active Sources'].json.id;
const categorySlug = $node['Fetch Active Sources'].json.category_slug;

try {
  const response = $input.item.json;
  const idList = response.esearchresult?.idlist || [];

  if (idList.length === 0) {
    return [];
  }

  // Store IDs for next step to fetch details
  return [{
    json: {
      sourceId,
      categorySlug,
      pmids: idList
    }
  }];

} catch (error) {
  console.error('Error parsing PubMed response:', error.message);
  throw new Error(`Failed to parse PubMed response: ${error.message}`);
}

return items.map(item => ({ json: item }));

// Parse PubMed XML details
const xml2js = require('xml2js');
const parser = new xml2js.Parser();

const items = [];
const sourceId = $node['Parse PubMed IDs'].json.sourceId;
const categorySlug = $node['Parse PubMed IDs'].json.categorySlug;

try {
  const result = await parser.parseStringPromise($input.item.json.body);
  const articles = result.PubmedArticleSet?.PubmedArticle || [];

  for (const article of articles) {
    const medline = article.MedlineCitation[0];
    const pubmedData = article.PubmedData[0];

    const pmid = medline.PMID[0]._;
    const articleData = medline.Article[0];

    // Get publication date
    const pubDate = articleData.Journal[0].JournalIssue[0].PubDate[0];
    const year = pubDate.Year ? pubDate.Year[0] : new Date().getFullYear();
    const month = pubDate.Month ? pubDate.Month[0] : '01';
    const day = pubDate.Day ? pubDate.Day[0] : '01';
    const publishedAt = new Date(`${year}-${month}-${day}`);
    const daysOld = (Date.now() - publishedAt.getTime()) / (1000 * 60 * 60 * 24);

    // Extract title
    const title = articleData.ArticleTitle[0];

    // Extract abstract
    let abstract = '';
    if (articleData.Abstract && articleData.Abstract[0].AbstractText) {
      abstract = articleData.Abstract[0].AbstractText
        .map(at => typeof at === 'string' ? at : at._)
        .join(' ');
    }
    const abstractWords = abstract.split(/\s+/).length;

    // Extract authors
    const authors = articleData.AuthorList ? 
      articleData.AuthorList[0].Author
        .map(a => {
          const lastName = a.LastName ? a.LastName[0] : '';
          const foreName = a.ForeName ? a.ForeName[0] : '';
          return `${foreName} ${lastName}`.trim();
        })
        .filter(a => a)
        .join(', ') : 'Unknown';

    // Extract keywords/mesh terms
    const keywords = [];
    if (medline.MeshHeadingList) {
      keywords.push(...medline.MeshHeadingList[0].MeshHeading
        .map(mh => mh.DescriptorName[0]._));
    }
    if (medline.KeywordList) {
      keywords.push(...medline.KeywordList[0].Keyword
        .map(k => typeof k === 'string' ? k : k._));
    }

    // Calculate quality score
    let qualityScore = 0.75; // Base score for PubMed papers

    // Bonus for good abstract length
    if (abstractWords >= 150 && abstractWords <= 500) {
      qualityScore += 0.1;
    }

    // Bonus for recent publication
    if (daysOld < 30) {
      qualityScore += 0.1;
    } else if (daysOld < 180) {
      qualityScore += 0.05;
    }

    // Bonus for rich metadata
    if (keywords.length > 5) {
      qualityScore += 0.05;
    }

    // Auto-tagging
    const tags = [];
    const titleLower = title.toLowerCase();
    const abstractLower = abstract.toLowerCase();

    // Medical specialties
    if (titleLower.includes('cancer') || titleLower.includes('oncology')) tags.push('oncology');
    if (titleLower.includes('cardio') || titleLower.includes('heart')) tags.push('cardiology');
    if (titleLower.includes('neuro') || titleLower.includes('brain')) tags.push('neuroscience');
    if (titleLower.includes('immuno') || titleLower.includes('vaccine')) tags.push('immunology');

    // Research type
    if (titleLower.includes('review') || titleLower.includes('meta-analysis')) tags.push('review');
    if (titleLower.includes('trial') || titleLower.includes('study')) tags.push('clinical-study');
    if (titleLower.includes('case report')) tags.push('case-report');

    // Difficulty
    if (titleLower.includes('introduction') || titleLower.includes('overview')) {
      tags.push('beginner-friendly');
    } else if (abstractLower.includes('novel') || abstractLower.includes('advanced')) {
      tags.push('advanced');
    } else {
      tags.push('intermediate');
    }

    // DOI
    let doi = null;
    if (pubmedData.ArticleIdList) {
      const doiArticleId = pubmedData.ArticleIdList[0].ArticleId
        .find(id => id.$.IdType === 'doi');
      if (doiArticleId) doi = doiArticleId._;
    }

    items.push({
      sourceId,
      externalId: `pubmed_${pmid}`,
      contentType: 'paper',
      source: 'pubmed',
      categorySlug,
      title: title.substring(0, 500),
      description: abstract.substring(0, 1000),
      url: `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`,
      thumbnailUrl: null,
      author: authors.substring(0, 255),
      publishedAt: publishedAt.toISOString(),
      wordCount: abstractWords,
      language: 'en',
      metadata: {
        pmid,
        doi,
        journal: articleData.Journal[0].Title ? articleData.Journal[0].Title[0] : null,
        volume: articleData.Journal[0].JournalIssue[0].Volume ? 
          articleData.Journal[0].JournalIssue[0].Volume[0] : null,
        meshTerms: keywords.slice(0, 20),
        publicationType: articleData.PublicationTypeList ? 
          articleData.PublicationTypeList[0].PublicationType.map(pt => pt._) : []
      },
      qualityScore: Math.min(qualityScore, 1.0),
      popularityScore: 0,
      tags
    });
  }
} catch (error) {
  console.error('Error parsing PubMed XML:', error.message);
  throw new Error(`Failed to parse PubMed details: ${error.message}`);
}

return items.map(item => ({ json: item }));

// Add tags to the newly inserted content
const contentId = $node['Insert Paper'].json.id;
const tags = $node['Merge All Papers'].json.tags || [];

if (tags.length === 0) {
  return [];
}

return [{
  json: {
    contentId,
    tags
  }
}];

// Format execution summary
const totalPapers = $('Merge All Papers').all().length;
const qualityFiltered = $('Quality Filter', 0).all().length;
const duplicates = totalPapers - qualityFiltered;
const newPapers = $('Insert Paper').all().length;

const sources = $('Fetch Active Sources').all();
const arxivSources = sources.filter(s => s.json.source_url.includes('arxiv')).length;
const pubmedSources = sources.filter(s => !s.json.source_url.includes('arxiv')).length;

return [{
  json: {
    workflow: 'Research Paper Aggregator - Advanced',
    executedAt: new Date().toISOString(),
    stats: {
      sourcesProcessed: sources.length,
      arxivSources,
      pubmedSources,
      totalPapersFetched: totalPapers,
      qualityFiltered,
      duplicates,
      newPapersInserted: newPapers
    },
    success: true
  }
}];
